-- OWNER-ONLY DEPLOYMENT. No API EXECUTE grants; notifications remain disabled.
-- GENERATED by local_test/generate_upgrade.py. Metadata only; invokes no RPC.
BEGIN TRANSACTION READ ONLY;
SET LOCAL search_path = pg_catalog;
SET LOCAL statement_timeout = '15s';
DO $verify$
DECLARE
  target_schema oid := to_regnamespace('safe_walk_nearby');
  postgis_schema text;
  geography_type oid;
  expected record;
  actual record;
  api_role text;
  relation record;
  normalized_check text;
BEGIN
  IF target_schema IS NULL THEN
    RAISE EXCEPTION 'safe_walk_nearby does not exist';
  END IF;
  SELECT n.nspname INTO STRICT postgis_schema
  FROM pg_extension e JOIN pg_namespace n ON n.oid = e.extnamespace
  WHERE e.extname = 'postgis';
  geography_type := to_regtype(format('%I.geography', postgis_schema));

  IF (SELECT count(*) FROM pg_class
      WHERE relnamespace = target_schema AND relkind = 'r') <> 8
      OR EXISTS (SELECT 1 FROM pg_class WHERE relnamespace = target_schema
                 AND relkind NOT IN ('r', 'i'))
      OR (SELECT count(*) FROM pg_proc WHERE pronamespace = target_schema) <> 1
      OR to_regprocedure('safe_walk_nearby.purge_expired()') IS NULL
      OR EXISTS (SELECT 1 FROM pg_policy p JOIN pg_class c ON c.oid = p.polrelid
                 WHERE c.relnamespace = target_schema)
      OR EXISTS (SELECT 1 FROM pg_trigger t JOIN pg_class c ON c.oid = t.tgrelid
                 WHERE c.relnamespace = target_schema AND NOT t.tgisinternal) THEN
    RAISE EXCEPTION 'Expected eight ordinary tables, indexes, one private function, zero policies/user triggers';
  END IF;

  IF (SELECT count(*) FROM pg_attribute a JOIN pg_class c ON c.oid = a.attrelid
      WHERE c.relnamespace = target_schema AND c.relkind = 'r'
        AND a.attnum > 0 AND NOT a.attisdropped) <> 37 THEN
    RAISE EXCEPTION 'Expected exactly the 37 backend columns';
  END IF;
  FOR expected IN SELECT * FROM (VALUES
    ('helper_areas', 'id', 'uuid', true, 'gen_random_uuid()'),
    ('helper_areas', 'user_id', 'uuid', true, NULL),
    ('helper_areas', 'center', 'geography', true, NULL),
    ('helper_areas', 'radius_m', 'integer', true, NULL),
    ('helper_areas', 'created_at', 'timestamptz', true, 'now()'),
    ('contact_invites', 'code_hash', 'text', true, NULL),
    ('contact_invites', 'owner_id', 'uuid', true, NULL),
    ('contact_invites', 'display_name', 'text', true, NULL),
    ('contact_invites', 'created_at', 'timestamptz', true, 'now()'),
    ('contact_invites', 'expires_at', 'timestamptz', true, NULL),
    ('trusted_contacts', 'id', 'uuid', true, 'gen_random_uuid()'),
    ('trusted_contacts', 'owner_id', 'uuid', true, NULL),
    ('trusted_contacts', 'contact_id', 'uuid', true, NULL),
    ('trusted_contacts', 'display_name', 'text', true, NULL),
    ('trusted_contacts', 'created_at', 'timestamptz', true, 'now()'),
    ('contact_invite_attempts', 'user_id', 'uuid', true, NULL),
    ('contact_invite_attempts', 'attempted_at', 'timestamptz', true, 'now()'),
    ('helper_profiles', 'user_id', 'uuid', true, NULL::text),
    ('helper_profiles', 'consent_version', 'text', true, NULL),
    ('helper_profiles', 'consented_at', 'timestamptz', true, NULL),
    ('helper_profiles', 'revoked_at', 'timestamptz', false, NULL),
    ('helper_locations', 'user_id', 'uuid', true, NULL),
    ('helper_locations', 'geog', 'geography', true, NULL),
    ('helper_locations', 'accuracy_m', 'real', false, NULL),
    ('helper_locations', 'reported_at', 'timestamptz', true, NULL),
    ('helper_locations', 'expires_at', 'timestamptz', true, NULL),
    ('alerts', 'id', 'uuid', true, 'gen_random_uuid()'),
    ('alerts', 'sender_id', 'uuid', true, NULL),
    ('alerts', 'client_request_id', 'uuid', true, NULL),
    ('alerts', 'geog', 'geography', true, NULL),
    ('alerts', 'radius_m', 'integer', true, '500'),
    ('alerts', 'created_at', 'timestamptz', true, 'now()'),
    ('alerts', 'expires_at', 'timestamptz', true, NULL),
    ('alert_deliveries', 'alert_id', 'uuid', true, NULL),
    ('alert_deliveries', 'recipient_id', 'uuid', true, NULL),
    ('alert_deliveries', 'delivered_at', 'timestamptz', true, 'now()'),
    ('alert_deliveries', 'seen_at', 'timestamptz', false, NULL)
  ) AS columns(table_name, column_name, type_name, required, default_expression)
  LOOP
    SELECT a.atttypid, a.atttypmod, a.attnotnull,
      pg_get_expr(d.adbin, d.adrelid) AS default_expression
    INTO actual FROM pg_attribute a
    LEFT JOIN pg_attrdef d ON d.adrelid = a.attrelid AND d.adnum = a.attnum
    WHERE a.attrelid = to_regclass(format('safe_walk_nearby.%I', expected.table_name))
      AND a.attname = expected.column_name AND a.attnum > 0 AND NOT a.attisdropped;
    IF NOT FOUND OR actual.attnotnull IS DISTINCT FROM expected.required
        OR actual.default_expression IS DISTINCT FROM expected.default_expression THEN
      RAISE EXCEPTION 'Missing column or nullability/default mismatch: %.%',
        expected.table_name, expected.column_name;
    END IF;
    IF expected.type_name = 'geography' THEN
      IF actual.atttypid IS DISTINCT FROM geography_type OR
          format_type(actual.atttypid, actual.atttypmod)
            IS DISTINCT FROM format('%I.geography(Point,4326)', postgis_schema) THEN
        RAISE EXCEPTION 'Expected installed PostGIS geography(Point,4326): %.%',
          expected.table_name, expected.column_name;
      END IF;
    ELSIF actual.atttypid IS DISTINCT FROM to_regtype(expected.type_name)
        OR actual.atttypmod <> -1 THEN
      RAISE EXCEPTION 'Column type mismatch: %.%', expected.table_name, expected.column_name;
    END IF;
  END LOOP;

  -- Verify the exact PK/UNIQUE keys through their ordered column names.
  FOR expected IN SELECT * FROM (VALUES
    ('helper_areas', 'p', ARRAY['id']),
    ('contact_invites', 'p', ARRAY['code_hash']),
    ('trusted_contacts', 'p', ARRAY['id']),
    ('trusted_contacts', 'u', ARRAY['owner_id', 'contact_id']),
    ('helper_profiles', 'p', ARRAY['user_id']),
    ('helper_locations', 'p', ARRAY['user_id']),
    ('alerts', 'p', ARRAY['id']),
    ('alerts', 'u', ARRAY['sender_id', 'client_request_id']),
    ('alert_deliveries', 'p', ARRAY['alert_id', 'recipient_id'])
  ) AS keys(table_name, kind, column_names)
  LOOP
    IF NOT EXISTS (
      SELECT 1 FROM pg_constraint c
      WHERE c.conrelid = to_regclass(format('safe_walk_nearby.%I', expected.table_name))
        AND c.contype::text = expected.kind AND c.convalidated
        AND NOT c.condeferrable
        AND (SELECT array_agg(a.attname::text ORDER BY k.position)
             FROM unnest(c.conkey) WITH ORDINALITY AS k(attribute_number, position)
             JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = k.attribute_number)
          = expected.column_names
    ) THEN
      RAISE EXCEPTION 'Missing design PK/UNIQUE: % %', expected.table_name, expected.column_names;
    END IF;
  END LOOP;

  FOR expected IN SELECT * FROM (VALUES
    ('helper_areas', 'user_id', 'safe_walk_nearby.helper_profiles', 'user_id'),
    ('contact_invites', 'owner_id', 'auth.users', 'id'),
    ('trusted_contacts', 'owner_id', 'auth.users', 'id'),
    ('trusted_contacts', 'contact_id', 'auth.users', 'id'),
    ('contact_invite_attempts', 'user_id', 'auth.users', 'id'),
    ('helper_profiles', 'user_id', 'auth.users', 'id'),
    ('helper_locations', 'user_id', 'safe_walk_nearby.helper_profiles', 'user_id'),
    ('alerts', 'sender_id', 'auth.users', 'id'),
    ('alert_deliveries', 'alert_id', 'safe_walk_nearby.alerts', 'id'),
    ('alert_deliveries', 'recipient_id', 'auth.users', 'id')
  ) AS fks(table_name, column_name, referenced_table, referenced_column)
  LOOP
    IF NOT EXISTS (
      SELECT 1 FROM pg_constraint c
      JOIN pg_attribute a ON a.attrelid = c.conrelid AND c.conkey = ARRAY[a.attnum]
      JOIN pg_attribute r ON r.attrelid = c.confrelid AND c.confkey = ARRAY[r.attnum]
      WHERE c.conrelid = to_regclass(format('safe_walk_nearby.%I', expected.table_name))
        AND c.contype = 'f' AND c.convalidated AND NOT c.condeferrable
        AND c.confrelid = to_regclass(expected.referenced_table)
        AND a.attname = expected.column_name AND r.attname = expected.referenced_column
        AND c.confdeltype = 'c' AND c.confupdtype = 'a' AND c.confmatchtype = 's'
    ) THEN
      RAISE EXCEPTION 'Missing validated CASCADE FK: %.%', expected.table_name, expected.column_name;
    END IF;
  END LOOP;
  IF (SELECT count(*) FROM pg_constraint c JOIN pg_class t ON t.oid = c.conrelid
      WHERE t.relnamespace = target_schema) <> 26 THEN
    RAISE EXCEPTION 'Expected exactly 7 PK, 10 FK, 2 UNIQUE and 7 CHECK constraints';
  END IF;

  -- Normalize SQL keyword case, rendering parentheses/whitespace and numeric casts.
  -- No substring match: changed operators, constants or extra clauses fail.
  FOR expected IN SELECT * FROM (VALUES
    ('helper_locations', 'accuracy_misnulloraccuracy_m>=0'), ('alerts', 'radius_m=500'),
    ('helper_profiles', 'char_lengthconsent_version>=1andchar_lengthconsent_version<=64'),
    ('helper_areas', 'radius_m>=500andradius_m<=1000'),
    ('contact_invites', 'char_lengthdisplay_name>=1andchar_lengthdisplay_name<=20')
  ) AS checks(table_name, expression)
  LOOP
    SELECT lower(regexp_replace(
      regexp_replace(pg_get_expr(c.conbin, c.conrelid),
        '::(double precision|real|integer|numeric)', '', 'g'),
      '[[:space:]()]', '', 'g'))
    INTO normalized_check FROM pg_constraint c
    WHERE c.conrelid = to_regclass(format('safe_walk_nearby.%I', expected.table_name))
      AND c.contype = 'c' AND c.convalidated;
    IF NOT FOUND OR normalized_check IS DISTINCT FROM expected.expression THEN
      RAISE EXCEPTION 'CHECK mismatch on %', expected.table_name;
    END IF;
  END LOOP;

  IF NOT EXISTS (
    SELECT 1 FROM pg_index i JOIN pg_class idx ON idx.oid = i.indexrelid
    JOIN pg_am am ON am.oid = idx.relam
    JOIN pg_attribute a ON a.attrelid = i.indrelid AND a.attname = 'geog'
    WHERE i.indrelid = 'safe_walk_nearby.helper_locations'::regclass
      AND am.amname = 'gist' AND i.indisvalid AND i.indisready
      AND i.indnkeyatts = 1 AND i.indnatts = 1 AND i.indkey[0] = a.attnum
      AND i.indpred IS NULL AND i.indexprs IS NULL
  ) THEN
    RAISE EXCEPTION 'Missing valid, unconditional single-column geog GiST index';
  END IF;

  -- PUBLIC is a pseudo-role: inspect raw ACLs as well as each real API role's
  -- effective privileges, which include grants inherited from other roles.
  IF EXISTS (SELECT 1 FROM pg_namespace n,
      LATERAL aclexplode(coalesce(n.nspacl, acldefault('n', n.nspowner))) a
      WHERE n.oid = target_schema AND a.grantee = 0)
      OR EXISTS (SELECT 1 FROM pg_class c,
      LATERAL aclexplode(coalesce(c.relacl, acldefault('r', c.relowner))) a
      WHERE c.relnamespace = target_schema AND c.relkind = 'r' AND a.grantee = 0) THEN
    RAISE EXCEPTION 'PUBLIC retains schema or table ACL';
  END IF;
  FOREACH api_role IN ARRAY ARRAY['anon', 'authenticated', 'service_role'] LOOP
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = api_role) THEN
      RAISE EXCEPTION 'Expected API role % is missing', api_role;
    END IF;
    IF has_schema_privilege(api_role, target_schema, 'USAGE') OR
        has_schema_privilege(api_role, target_schema, 'CREATE') THEN
      RAISE EXCEPTION 'API role % has effective schema access', api_role;
    END IF;
    FOR relation IN SELECT oid, relname, relrowsecurity FROM pg_class
      WHERE relnamespace = target_schema AND relkind = 'r'
    LOOP
      IF NOT relation.relrowsecurity OR EXISTS (
        SELECT 1 FROM unnest(ARRAY[
          'SELECT', 'INSERT', 'UPDATE', 'DELETE', 'TRUNCATE', 'REFERENCES', 'TRIGGER'
        ]) AS privilege_name
        WHERE has_table_privilege(api_role, relation.oid, privilege_name)
      ) OR has_any_column_privilege(api_role, relation.oid, 'SELECT')
        OR has_any_column_privilege(api_role, relation.oid, 'INSERT')
        OR has_any_column_privilege(api_role, relation.oid, 'UPDATE')
        OR has_any_column_privilege(api_role, relation.oid, 'REFERENCES') THEN
        RAISE EXCEPTION 'RLS/effective table or column ACL mismatch: % / %', api_role, relation.relname;
      END IF;
    END LOOP;
  END LOOP;
END
$verify$;

-- Generator fragment; run 04_verify_backend.sql, not this fragment on its own.
DO $backend$
DECLARE
  expected record;
  actual record;
  api_role text;
  relation record;
  expression text;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_extension e JOIN pg_namespace n ON n.oid=e.extnamespace
      WHERE e.extname='postgis' AND n.nspname='public') OR NOT EXISTS (
      SELECT 1 FROM pg_extension e JOIN pg_namespace n ON n.oid=e.extnamespace
      WHERE e.extname='pgcrypto' AND n.nspname='extensions') THEN
    RAISE EXCEPTION 'Extension schema mismatch';
  END IF;
  IF (SELECT count(*) FROM pg_proc WHERE pronamespace='public'::regnamespace
      AND left(proname,7)='nearby_') <> 13 THEN
    RAISE EXCEPTION 'Expected exactly 13 nearby RPCs; unexpected overloads fail';
  END IF;
  FOR expected IN SELECT * FROM (VALUES
    ('public.nearby_helper_opt_in(text)', 'afc814bc8caf22f1c2056f3712b6a016', true, 'void', ARRAY['p_consent_version']::text[]),
    ('public.nearby_helper_opt_out()', 'bebce5ea4bbc34549a9cd139a5fb739f', true, 'void', ARRAY[]::text[]),
    ('public.nearby_helper_report_location(double precision,double precision,real)', '01d33371d089f7522010f7c37c225125', true, 'void', ARRAY['p_lat','p_lng','p_accuracy_m']::text[]),
    ('public.nearby_sos_send(double precision,double precision,uuid)', '0527e5ef874d9a780da3413408421d2e', true, 'integer', ARRAY['p_lat','p_lng','p_client_request_id']::text[]),
    ('public.nearby_helper_fetch_alerts()', '865b6c8bb8e0b9a9c5ffb600164af1f4', true, 'table(alert_id uuid,lat double precision,lng double precision,radius_m integer,created_at timestamptz,expires_at timestamptz,from_contact boolean,sender_name text)', ARRAY[]::text[]),
    ('public.nearby_helper_set_areas(jsonb)', '91455a3daaaec9605c663292d5181d1a', true, 'void', ARRAY['p_areas']::text[]),
    ('public.nearby_helper_get_areas()', 'f0710f2435f490a4805432979d9b4092', true, 'table(lat double precision,lng double precision,radius_m integer)', ARRAY[]::text[]),
    ('public.nearby_contact_invite_create(text)', 'ab7332c761bfad42091d64aca4a23af3', true, 'table(code text,expires_at timestamptz)', ARRAY['p_display_name']::text[]),
    ('public.nearby_contact_invite_accept(text)', 'b1f59a6bd51057ee0495fade22f66cbc', true, 'text', ARRAY['p_code']::text[]),
    ('public.nearby_contact_list_mine()', '746d6bf81ee6c1480175cc82575bed70', true, 'table(link_id uuid,since timestamptz)', ARRAY[]::text[]),
    ('public.nearby_contact_remove(uuid)', 'c185ad111eb51bce69c2c3583a3ad87d', true, 'void', ARRAY['p_link_id']::text[]),
    ('public.nearby_contact_following()', 'd23a8253d3c9bf651cbd80aa2fc00628', true, 'table(link_id uuid,display_name text,since timestamptz)', ARRAY[]::text[]),
    ('public.nearby_contact_unfollow(uuid)', '82dc472f38b4b528591de51b892f9c39', true, 'void', ARRAY['p_link_id']::text[]),
    ('safe_walk_nearby.purge_expired()', '792d3b1e0fbebbb225bd4a9ad0e6f88b', false, 'void', ARRAY[]::text[])
  ) AS functions(signature, body_md5, client_callable, result, argument_names)
  LOOP
    SELECT p.*, pg_get_function_result(p.oid) AS result,
      pg_get_userbyid(p.proowner) AS owner,
      l.lanname AS language
    INTO actual FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang
    WHERE p.oid=to_regprocedure(expected.signature);
    IF NOT FOUND OR NOT actual.prosecdef OR actual.prokind <> 'f'
        OR actual.provolatile <> 'v' OR actual.proisstrict
        OR actual.proleakproof OR actual.proparallel <> 'u'
        OR actual.proconfig IS DISTINCT FROM ARRAY['search_path=""']
        OR md5(replace(actual.prosrc, E'\r\n', E'\n')) <> expected.body_md5
        OR lower(regexp_replace(regexp_replace(replace(actual.result, 'timestamp with time zone', 'timestamptz'),
             '\s+', ' ', 'g'), '\s*([(),])\s*', '\1', 'g')) <> expected.result
        OR coalesce(actual.proargnames[1:actual.pronargs], ARRAY[]::text[]) <> expected.argument_names
        OR actual.owner <> pg_get_userbyid((SELECT nspowner FROM pg_namespace
             WHERE oid='safe_walk_nearby'::regnamespace))
        OR actual.language <> (CASE WHEN expected.client_callable THEN 'plpgsql' ELSE 'sql' END) THEN
      RAISE EXCEPTION 'RPC signature/body/security metadata mismatch: %', expected.signature;
    END IF;
    IF (actual.pronargdefaults <> CASE WHEN actual.proname='nearby_helper_report_location' THEN 1 ELSE 0 END)
        OR (actual.pronargdefaults=1 AND
            pg_get_expr(actual.proargdefaults, 0) IS DISTINCT FROM 'NULL::real') THEN
      RAISE EXCEPTION 'Unexpected RPC defaults: %', expected.signature;
    END IF;
    IF EXISTS (SELECT 1 FROM aclexplode(coalesce(actual.proacl,
        acldefault('f', actual.proowner))) a WHERE a.grantee <> actual.proowner
        AND true) THEN
      RAISE EXCEPTION 'Unexpected explicit function ACL: %', expected.signature;
    END IF;
    FOREACH api_role IN ARRAY ARRAY['anon','authenticated','service_role'] LOOP
      IF has_function_privilege(api_role, actual.oid, 'EXECUTE') IS DISTINCT FROM
          false THEN
        RAISE EXCEPTION 'Effective RPC ACL mismatch: % / %', expected.signature, api_role;
      END IF;
    END LOOP;
  END LOOP;

  IF (SELECT array_agg(lower(regexp_replace(pg_get_expr(conbin,conrelid),
          '[[:space:]()]', '', 'g')) ORDER BY lower(pg_get_expr(conbin,conrelid)))
      FROM pg_constraint WHERE conrelid='safe_walk_nearby.trusted_contacts'::regclass AND contype='c')
      IS DISTINCT FROM ARRAY['char_lengthdisplay_name>=1andchar_lengthdisplay_name<=20',
                             'owner_id<>contact_id'] THEN
    RAISE EXCEPTION 'Trusted contacts CHECK mismatch';
  END IF;
  FOR expected IN SELECT * FROM (VALUES
    ('helper_locations','geog','gist',ARRAY['geog']),
    ('helper_locations','expires','btree',ARRAY['expires_at']),
    ('alerts','sender','btree',ARRAY['sender_id','created_at']),
    ('alerts','expires','btree',ARRAY['expires_at']),
    ('alert_deliveries','recipient','btree',ARRAY['recipient_id']),
    ('helper_areas','center','gist',ARRAY['center']),
    ('helper_areas','user','btree',ARRAY['user_id']),
    ('contact_invites','owner','btree',ARRAY['owner_id']),
    ('trusted_contacts','owner','btree',ARRAY['owner_id']),
    ('trusted_contacts','contact','btree',ARRAY['contact_id']),
    ('contact_invite_attempts','attempts','btree',ARRAY['user_id','attempted_at'])
  ) AS indexes(table_name, label, method, columns)
  LOOP
    IF NOT EXISTS (
      SELECT 1 FROM pg_index i JOIN pg_class idx ON idx.oid=i.indexrelid
      JOIN pg_am am ON am.oid=idx.relam
      WHERE i.indrelid=to_regclass(format('safe_walk_nearby.%I',expected.table_name))
        AND i.indisvalid AND i.indisready AND i.indpred IS NULL AND i.indexprs IS NULL
        AND am.amname=expected.method AND i.indnkeyatts=cardinality(expected.columns)
        AND i.indnatts=i.indnkeyatts
        AND (SELECT array_agg(a.attname::text ORDER BY k.position)
          FROM unnest(i.indkey) WITH ORDINALITY k(attnum,position)
          JOIN pg_attribute a ON a.attrelid=i.indrelid AND a.attnum=k.attnum) = expected.columns
    ) THEN
      RAISE EXCEPTION 'Missing valid unconditional index: % / %', expected.table_name, expected.label;
    END IF;
  END LOOP;
  -- PUBLIC column grants can be hidden by schema denial; reject those too.
  IF EXISTS (SELECT 1 FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid,
      LATERAL aclexplode(a.attacl) acl WHERE c.relnamespace='safe_walk_nearby'::regnamespace
      AND acl.grantee <> c.relowner) THEN
    RAISE EXCEPTION 'Unexpected non-owner column ACL';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_namespace n,
      LATERAL aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) a
      WHERE n.oid='safe_walk_nearby'::regnamespace AND a.grantee <> n.nspowner)
      OR EXISTS (SELECT 1 FROM pg_class c,
      LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a
      WHERE c.relnamespace='safe_walk_nearby'::regnamespace AND c.relkind='r'
      AND a.grantee <> c.relowner) THEN
    RAISE EXCEPTION 'Unexpected non-owner schema/table ACL';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_class c WHERE c.relnamespace='safe_walk_nearby'::regnamespace
      AND c.relowner <> (SELECT nspowner FROM pg_namespace WHERE oid=c.relnamespace)) THEN
    RAISE EXCEPTION 'Unexpected relation owner';
  END IF;
END $backend$;

